        legSolver = new LegSolverQuadruped(0.3F, 0.35F, 0.2F, 1.45F, 1.0F);
        this.flightManager = new IafDragonFlightManager(this);
        this.logic = createDragonLogic();
        this.noCulling = true;
        switchNavigator(0);
        randomizeAttacks();
        resetParts(1);
    }

