		if (level != null) {
			BlockPos mainPos = getMainPos();
			if (!mainPos.equals(worldPosition)) {
				return level.getBlockEntity(mainPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).orElse(null);
			}
		}
		return this;
	}

	public void dropSecondPartContents(ChestBlock chestBlock, BlockPos dropPosition) {
		if (isLinkedStorage()) {
			return;
		}
		InventoryHandler invHandler = getStorageWrapper().getInventoryHandler();

		List<ItemStack> dropItems = new ArrayList<>();

		for (int slot = chestBlock.getNumberOfInventorySlots(); slot < invHandler.getSlots(); slot++) {
			ItemStack slotStack = invHandler.getSlotStack(slot);

			if (!slotStack.isEmpty()) {
				dropItems.add(slotStack.copy());
				invHandler.setStackInSlot(slot, ItemStack.EMPTY);
			}
		}

		if (level instanceof ServerLevel serverLevel) {
			serverLevel.getServer().tell(new TickTask(serverLevel.getServer().getTickCount(), () -> dropItems
					.forEach(itemStack -> Containers.dropItemStack(serverLevel, dropPosition.getX(), dropPosition.getY(), dropPosition.getZ(), itemStack))));
		}

		int inventorySlotDiff = chestBlock.getNumberOfInventorySlots() - invHandler.getSlots();

		changeStorageSize(inventorySlotDiff, 0);
		deleteSettingsFromSlot(this, chestBlock.getNumberOfInventorySlots());
		getStorageWrapper().getSettingsHandler().getTypeCategory(ItemDisplaySettingsCategory.class).setDisplaySide(DisplaySide.FRONT);
		getStorageWrapper().getUpgradeHandler().refreshUpgradeWrappers();
		WorldHelper.notifyBlockUpdate(this);
	}

	public void setDestroyedByPlayer(boolean linkedStorage) {
		isDestroyedByPlayer = true;
		wasLinkedStorageWhenDestroyed = linkedStorage;
	}

	public void prepareLinkedPrimaryDoubleChestDrop(@Nullable LinkedStorageEndpointData endpoint) {
		linkedPrimaryDoubleChestDropEndpoint = endpoint;
	}

	@Nullable
	public LinkedStorageEndpointData getLinkedPrimaryDoubleChestDropEndpoint() {
		return linkedPrimaryDoubleChestDropEndpoint;
	}

	public boolean isPrimaryLinkedStorage() {
		return getStorageWrapper().getLinkedStorageEndpointRole().orElse(null) == LinkedStorageEndpointRole.PRIMARY;
	}

	@Override
	public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		if (!isBeingUpgraded() && getBlockState().getValue(ChestBlock.TYPE) == ChestType.SINGLE) {
			if (getBlockState().getBlock() instanceof ChestBlock chestBlock
					&& getStorageWrapper().getInventoryHandler().getSlots() > chestBlock.getNumberOfInventorySlots()) {
				dropSecondPartContents(chestBlock, worldPosition);
			}
		}
	}

	@Override
	public void changeSlots(int newSlots) {
		if (hasStorageData() && !isBeingUpgraded()) {
			super.changeSlots(newSlots);
		}
	}

	@Override
	public void setShouldBeOpen(boolean shouldBeOpen) {
		chestLidController.shouldBeOpen(shouldBeOpen);
		if (level != null) {
			runOnTheOtherPart(level, worldPosition, (be, pos) -> be.chestLidController.shouldBeOpen(shouldBeOpen));
		}
	}

	public BlockPos getMainPos() {
		BlockState state = getBlockState();
		if (state.getValue(ChestBlock.TYPE) != ChestType.LEFT || level == null) {
			return worldPosition;
		}

		BlockPos mainPos = worldPosition.relative(ChestBlock.getConnectedDirection(state));
		BlockState mainState = level.getBlockState(mainPos);
		if (mainState.is(state.getBlock()) && mainState.getValue(ChestBlock.TYPE) == ChestType.RIGHT
				&& mainState.getValue(ChestBlock.FACING) == state.getValue(ChestBlock.FACING)
				&& mainPos.relative(ChestBlock.getConnectedDirection(mainState)).equals(worldPosition)) {
			return mainPos;
		}

		return worldPosition;
	}

	@Override
	public ILinkedStorageBlockEndpoint getLinkedStorageInteractionTarget() {
		ChestBlockEntity mainChest = getMainChestBlockEntity();
		return mainChest == null ? this : mainChest;
	}

	@Override
	public void setChanged() {
		super.setChanged();
		if (level != null && getBlockState().getValue(ChestBlock.TYPE) != ChestType.SINGLE && isMainChest()) {
			// need to update neighbors of the other half as well for comparators to pickup inventory changes
			runOnTheOtherPart(level, worldPosition, (be, pos) -> level.updateNeighbourForOutputSignal(pos, be.getBlockState().getBlock()));
		}
	}

	@Override
	public void linkToController(BlockPos controllerPos) {
		if (level != null) {
			BlockPos mainPos = getMainPos();
			if (!mainPos.equals(worldPosition)) {
				level.getBlockEntity(mainPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).ifPresent(be -> be.linkToController(controllerPos));
				return;
			}
		}
		if (level == null) {
			return;
		}
		super.linkToController(controllerPos);
	}

	@Override
	public void unlinkFromController() {
		if (level != null) {
			BlockPos mainPos = getMainPos();
			if (!mainPos.equals(worldPosition)) {
				level.getBlockEntity(mainPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).ifPresent(ChestBlockEntity::unlinkFromController);
				return;
			}
		}

		if (level == null) {
			return;
		}

		super.unlinkFromController();
	}
}

package net.p3pp3rf1y.sophisticatedstorage.block;

import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.nbt.Tag;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.DimensionDataStorage;
import net.neoforged.fml.util.thread.SidedThreadGroups;
import net.neoforged.neoforge.server.ServerLifecycleHooks;
import net.p3pp3rf1y.sophisticatedstorage.SophisticatedStorage;
import net.p3pp3rf1y.sophisticatedstorage.item.LegacyStorageBlockDataMigration;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

public class ItemContentsStorage extends SavedData {
	private static final String SAVED_DATA_NAME = SophisticatedStorage.MOD_ID;

	private final Map<UUID, CompoundTag> storageContents = new HashMap<>();
	private static final ItemContentsStorage clientStorageCopy = new ItemContentsStorage();

	private ItemContentsStorage() {
	}

	public static ItemContentsStorage get() {
		if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER) {
			MinecraftServer server = ServerLifecycleHooks.getCurrentServer();
			if (server != null) {
				ServerLevel overworld = server.getLevel(Level.OVERWORLD);
				// noinspection ConstantConditions - by this time overworld is loaded
				DimensionDataStorage storage = overworld.getDataStorage();
				return storage.computeIfAbsent(new Factory<>(ItemContentsStorage::new, ItemContentsStorage::load), SAVED_DATA_NAME);
			}
		}
		return clientStorageCopy;
	}

	public static ItemContentsStorage load(CompoundTag nbt, HolderLookup.Provider registries) {
		ItemContentsStorage storage = new ItemContentsStorage();
		readStorageContents(nbt, storage);
		return storage;
	}

	private static void readStorageContents(CompoundTag nbt, ItemContentsStorage storage) {
		ListTag storageContents = nbt.getList(nbt.contains("shulkerBoxContents") ? "shulkerBoxContents" : "storageContents", Tag.TAG_COMPOUND);
		for (Tag n : storageContents) {
			CompoundTag uuidContentsPair = (CompoundTag) n;
			UUID uuid = NbtUtils.loadUUID(Objects.requireNonNull(uuidContentsPair.get("uuid")));
			CompoundTag contents = uuidContentsPair.getCompound("contents");
			LegacyStorageBlockDataMigration.normalizeStorageContents(contents);
			storage.storageContents.put(uuid, contents);
		}
	}

	@Override
	public CompoundTag save(CompoundTag compound, HolderLookup.Provider registries) {
		CompoundTag ret = new CompoundTag();
		writeStorageContents(ret);
		return ret;
	}

	private void writeStorageContents(CompoundTag ret) {
		ListTag storageContentsNbt = new ListTag();
		for (Map.Entry<UUID, CompoundTag> entry : storageContents.entrySet()) {
			CompoundTag uuidContentsPair = new CompoundTag();
			uuidContentsPair.put("uuid", NbtUtils.createUUID(entry.getKey()));
			uuidContentsPair.put("contents", entry.getValue());
			storageContentsNbt.add(uuidContentsPair);
		}
		ret.put("storageContents", storageContentsNbt);
	}

	public boolean has(UUID storageUuid) {
		return storageContents.containsKey(storageUuid);
	}

	public Optional<CompoundTag> getStorageContents(UUID storageUuid) {
		return Optional.ofNullable(storageContents.get(storageUuid));
	}

	public CompoundTag getOrCreateStorageContents(UUID storageUuid) {
		return storageContents.computeIfAbsent(storageUuid, uuid -> {
			setDirty();
			return new CompoundTag();
		});
	}

	public void removeStorageContents(UUID storageUuid) {
		storageContents.remove(storageUuid);
		setDirty();
	}

	public void setStorageContents(UUID storageUuid, CompoundTag contents) {
		LegacyStorageBlockDataMigration.normalizeStorageContents(contents);
		storageContents.put(storageUuid, contents);
		setDirty();
	}
}

package net.p3pp3rf1y.sophisticatedstorage.block;

