public abstract class WoodStorageBlockBase extends StorageBlockBase implements IAdditionalDropDataBlock {
	public static final Map<WoodType, BlockFamily> CUSTOM_TEXTURE_WOOD_TYPES = ImmutableMap.<WoodType, BlockFamily>builder()
			.put(WoodType.ACACIA, BlockFamilies.ACACIA_PLANKS).put(WoodType.BIRCH, BlockFamilies.BIRCH_PLANKS)
			.put(WoodType.CRIMSON, BlockFamilies.CRIMSON_PLANKS).put(WoodType.DARK_OAK, BlockFamilies.DARK_OAK_PLANKS)
			.put(WoodType.JUNGLE, BlockFamilies.JUNGLE_PLANKS).put(WoodType.OAK, BlockFamilies.OAK_PLANKS).put(WoodType.SPRUCE, BlockFamilies.SPRUCE_PLANKS)
			.put(WoodType.WARPED, BlockFamilies.WARPED_PLANKS).put(WoodType.MANGROVE, BlockFamilies.MANGROVE_PLANKS)
			.put(WoodType.CHERRY, BlockFamilies.CHERRY_PLANKS).put(WoodType.BAMBOO, BlockFamilies.BAMBOO_PLANKS).build();

	protected WoodStorageBlockBase(Properties properties, Supplier<Integer> numberOfInventorySlotsSupplier, Supplier<Integer> numberOfUpgradeSlotsSupplier) {
		super(properties, numberOfInventorySlotsSupplier, numberOfUpgradeSlotsSupplier);
	}

	public void addNameWoodAndTintData(ItemStack stack, BlockGetter level, BlockPos pos) {
		WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> addNameWoodAndTintData(stack, be));
	}

	@Override
	public void onBlockExploded(BlockState state, Level level, BlockPos pos, Explosion explosion) {
		if (Config.COMMON.dropPacked.get()) {
			WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(wbe -> {
				if (!wbe.isLinkedStorage() && isNonEmpty(wbe)) {
					wbe.setPacked(true);
				}
			});
		}
		super.onBlockExploded(state, level, pos, explosion);
	}

	public void addDropData(ItemStack stack, StorageBlockEntity be) {
		if (be instanceof WoodStorageBlockEntity wbe) {
			addNameWoodAndTintData(stack, wbe);
			if (wbe.isLinkedStorage()) {
				wbe.copyLinkedStorageEndpointTo(stack);
				return;
			}
			boolean packed = wbe.isPacked() || shouldNonEmptyDropPacked(wbe);
			if (packed) {
				StorageWrapper storageWrapper = be.getStorageWrapper();
				UUID storageUuid = storageWrapper.getContentsUuid().orElse(UUID.randomUUID());
				CompoundTag storageContents = wbe.getStorageContentsTag();
				if (!storageContents.isEmpty()) {
					ItemContentsStorage.get().setStorageContents(storageUuid, storageContents);
					stack.set(ModCoreDataComponents.STORAGE_UUID, storageUuid);
				}
				WoodStorageBlockItem.setPacked(stack, true);
				StorageBlockItem.setShowsTier(stack, be.shouldShowTier());
				StorageBlockItem.setNumberOfInventorySlots(stack, storageWrapper.getInventoryHandler().getSlots());
				StorageBlockItem.setNumberOfUpgradeSlots(stack, storageWrapper.getUpgradeHandler().getSlots());
			}
		}
	}

	private static boolean shouldNonEmptyDropPacked(WoodStorageBlockEntity wbe) {
		if (!Config.COMMON.dropPacked.get()) {
			return false;
		}

		return isNonEmpty(wbe);
	}

	private static boolean isNonEmpty(WoodStorageBlockEntity wbe) {
		return !InventoryHelper.isEmpty(wbe.getStorageWrapper().getInventoryHandler()) || !InventoryHelper.isEmpty(wbe.getStorageWrapper().getUpgradeHandler());
	}

	protected void addNameWoodAndTintData(ItemStack stack, WoodStorageBlockEntity wbe) {
		if (stack.getItem() instanceof ITintableBlockItem tintableBlockItem) {
			int mainColor = wbe.getStorageWrapper().getMainColor();
			if (mainColor != -1) {
				tintableBlockItem.setMainColor(stack, mainColor);
			}
			int accentColor = wbe.getStorageWrapper().getAccentColor();
			if (accentColor != -1) {
				tintableBlockItem.setAccentColor(stack, accentColor);
			}
		}
		if (wbe.hasCustomName()) {
			stack.set(DataComponents.CUSTOM_NAME, wbe.getCustomName());
		}
		wbe.getWoodType().ifPresent(n -> WoodStorageBlockItem.setWoodType(stack, n));
	}

	@Override
	public void addCreativeTabItems(Consumer<ItemStack> itemConsumer) {
		if (!Config.CLIENT_SPEC.isLoaded() || Config.CLIENT.showSingleWoodVariantOnly.get()) {
			itemConsumer.accept(WoodStorageBlockItem.setWoodType(new ItemStack(this), WoodType.ACACIA));
		} else {
			CUSTOM_TEXTURE_WOOD_TYPES.keySet().forEach(woodType -> itemConsumer.accept(WoodStorageBlockItem.setWoodType(new ItemStack(this), woodType)));
			if (shouldShowGenericWoodVariants()) {
				GenericWoodStorageHelper.getGenericWoodTypes()
						.forEach(woodType -> itemConsumer.accept(WoodStorageBlockItem.setWoodType(new ItemStack(this), woodType)));
			}
		}

		if (isBasicTier()) {
			for (DyeColor color : DyeColor.values()) {
				ItemStack storageStack = new ItemStack(this);
				if (storageStack.getItem() instanceof ITintableBlockItem tintableBlockItem) {
					tintableBlockItem.setMainColor(storageStack, color.getTextureDiffuseColor());
					tintableBlockItem.setAccentColor(storageStack, color.getTextureDiffuseColor());
				}
				itemConsumer.accept(storageStack);
			}
			ItemStack storageStack = new ItemStack(this);
			if (storageStack.getItem() instanceof ITintableBlockItem tintableBlockItem) {
				tintableBlockItem.setMainColor(storageStack, DyeColor.YELLOW.getTextureDiffuseColor());
				tintableBlockItem.setAccentColor(storageStack, DyeColor.LIME.getTextureDiffuseColor());
			}
			itemConsumer.accept(storageStack);
		}
	}

	private boolean isBasicTier() {
		return this == ModBlocks.BARREL.get() || this == ModBlocks.CHEST.get() || this == ModBlocks.LIMITED_BARREL_1.get()
				|| this == ModBlocks.LIMITED_BARREL_2.get() || this == ModBlocks.LIMITED_BARREL_3.get() || this == ModBlocks.LIMITED_BARREL_4.get();
	}

	private boolean shouldShowGenericWoodVariants() {
		return isBasicTier() || Config.CLIENT.showHigherTierGenericWoodVariants.get();
	}

	@Override
	public ItemStack getCloneItemStack(BlockState state, HitResult target, LevelReader level, BlockPos pos, Player player) {
		ItemStack stack = new ItemStack(this);
		WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresentOrElse(be -> {
			if (be.isPacked()) {
				addDropData(stack, be);
			} else {
				addNameWoodAndTintData(stack, be);
			}
		}, () -> addNameWoodAndTintData(stack, level, pos));
		return stack;
	}

	@Override
	public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
		if (level.isClientSide()) {
			WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> setRenderBlockRenderProperties(stack, be));
			return;
		}
		ServerLevel serverLevel = (ServerLevel) level;

		WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(be -> {
			LegacyStorageBlockDataMigration.normalizeLegacyData(stack);
			UUID storageUuid = stack.get(ModCoreDataComponents.STORAGE_UUID);
			if (storageUuid != null && !StorageBlockEntity.hasLinkedStorageEndpoint(stack)) {
				ItemContentsStorage itemContentsStorage = ItemContentsStorage.get();
				if (itemContentsStorage.has(storageUuid)) {
					be.setBeingUpgraded(true);
					be.loadAdditional(itemContentsStorage.getOrCreateStorageContents(storageUuid), level.registryAccess());
					itemContentsStorage.removeStorageContents(storageUuid);
					setNewSize(stack, be);
					setTicking(level, pos, state, !be.getStorageWrapper().getUpgradeHandler().getWrappersThatImplement(ITickableUpgrade.class).isEmpty());
				} else {
					SophisticatedStorage.LOGGER
							.error("No storage contents found for uuid: " + storageUuid + " when placing " + stack.getHoverName().getString());
				}
			}

			if (stack.has(DataComponents.CUSTOM_NAME) && (!StorageBlockEntity.hasLinkedStorageEndpoint(stack)
					|| StorageBlockEntity.getLinkedStorageEndpointRole(stack).orElse(null) == LinkedStorageEndpointRole.PRIMARY)) {
				be.setCustomName(stack.getHoverName());
			}
			if (stack.has(DataComponents.CUSTOM_NAME)
					&& StorageBlockEntity.getLinkedStorageEndpointRole(stack).orElse(null) == LinkedStorageEndpointRole.PRIMARY) {
				StorageLinkedStorageEndpointAdapter.synchronizePrimaryCarrier(serverLevel, stack);
			}
			setRenderBlockRenderProperties(stack, be);
			boolean restoredLinkedStorage = !StorageBlockEntity.hasLinkedStorageEndpoint(stack);
			if (shouldRestoreLinkedStorageEndpoint(stack) && !restoredLinkedStorage) {
				if (placer instanceof Player player && player.getAbilities().instabuild && StorageBlockEntity.hasLinkedStorageEndpoint(stack)) {
					restoredLinkedStorage = be.restoreCreativeLinkedStorageEndpoint(serverLevel, stack);
				} else {
					restoredLinkedStorage = be.restoreLinkedStorageEndpoint(serverLevel, stack);
				}
			}

			be.getStorageWrapper().onInit(level);
			if (restoredLinkedStorage) {
				be.tryToAddToController();
			}

			if (placer != null && placer.getOffhandItem().getItem() == ModItems.STORAGE_TOOL.get()) {
				StorageToolItem.useOffHandOnPlaced(placer.getOffhandItem(), be);
			}
			be.setBeingUpgraded(false);
		});
	}

	protected boolean shouldRestoreLinkedStorageEndpoint(ItemStack stack) {
		return true;
	}

	private void setNewSize(ItemStack stack, WoodStorageBlockEntity be) {
		StorageWrapper storageWrapper = be.getStorageWrapper();
		InventoryHandler inventoryHandler = storageWrapper.getInventoryHandler();
		UpgradeHandler upgradeHandler = storageWrapper.getUpgradeHandler();
		storageWrapper.changeSize(StorageBlockItem.getNumberOfInventorySlots(stack) - inventoryHandler.getSlots(),
				StorageBlockItem.getNumberOfUpgradeSlots(stack) - upgradeHandler.getSlots());
	}

	protected void setRenderBlockRenderProperties(ItemStack stack, WoodStorageBlockEntity be) {
		WoodStorageBlockItem.getWoodType(stack).ifPresent(be::setWoodType);
		be.getStorageWrapper().setColors(StorageBlockItem.getMainColorFromComponentHolder(stack).orElse(-1),
				StorageBlockItem.getAccentColorFromComponentHolder(stack).orElse(-1));
		be.setUpdateBlockRender();
		WorldHelper.notifyBlockUpdate(be);
	}

	@Override
	public BlockState playerWillDestroy(Level level, BlockPos pos, BlockState state, Player player) {
		BlockState ret = super.playerWillDestroy(level, pos, state, player);
		WorldHelper.getBlockEntity(level, pos, WoodStorageBlockEntity.class).ifPresent(wbe -> {
			if (!wbe.isLinkedStorage() && Config.COMMON.dropPacked.get() && isNonEmpty(wbe)) {
				wbe.setPacked(true);
			}

			if (wbe.isPacked()) {
				if (player.isCreative() && (!InventoryHelper.isEmpty(wbe.getStorageWrapper().getInventoryHandler())
						|| !InventoryHelper.isEmpty(wbe.getStorageWrapper().getUpgradeHandler()))) {
					ItemStack drop = new ItemStack(this);
					addDropData(drop, wbe);
					ItemEntity itementity = new ItemEntity(level, pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D, drop);
					itementity.setDefaultPickUpDelay();
					level.addFreshEntity(itementity);
				}
			}
		});
		return ret;
	}

	@SuppressWarnings("java:S1172") // parameter is used in override
	protected boolean tryItemInteraction(Player player, InteractionHand hand, WoodStorageBlockEntity b, ItemStack stackInHand, Direction facing,
			BlockHitResult hitResult) {
		if (stackInHand.getItem() instanceof PackingTapeItem) {
			if (Config.COMMON.dropPacked.get()) {
				player.displayClientMessage(Component.translatable("gui.sophisticatedstorage.status.packing_tape_disabled"), true);
			} else {
				packStorage(player, hand, b, stackInHand);
			}
			return true;
		}
		return tryAddUpgrade(player, hand, b, stackInHand, facing, hitResult);
	}

	protected void packStorage(Player player, InteractionHand hand, WoodStorageBlockEntity b, ItemStack stackInHand) {
		if (b.isLinkedStorage()) {
			player.playNotifySound(SoundEvents.NOTE_BLOCK_BASS.value(), SoundSource.PLAYERS, 1, 0.7F);
			player.displayClientMessage(StorageTranslationHelper.INSTANCE.translStatusMessage("packing_tape_linked_storage"), true);
			return;
		}
		if (!player.isCreative()) {
			stackInHand.setDamageValue(stackInHand.getDamageValue() + 1);
			if (stackInHand.getDamageValue() >= stackInHand.getMaxDamage()) {
				player.setItemInHand(hand, ItemStack.EMPTY);
			}
		}

		BlockState blockState = b.getBlockState();
		if (blockState.getBlock() instanceof StorageBlockBase storageBlock && blockState.getValue(TICKING)) {
			storageBlock.setTicking(player.level(), b.getBlockPos(), blockState, false);
		}

		b.setPacked(true);

		b.removeFromController();

		WorldHelper.notifyBlockUpdate(b);
	}
}

package net.p3pp3rf1y.sophisticatedstorage.crafting;

import net.minecraft.core.HolderLookup;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.CraftingInput;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.ShapedRecipe;
import net.minecraft.world.level.Level;
import net.p3pp3rf1y.sophisticatedcore.crafting.IWrapperRecipe;
import net.p3pp3rf1y.sophisticatedcore.crafting.RecipeWrapperSerializer;
import net.p3pp3rf1y.sophisticatedcore.init.ModCoreDataComponents;
import net.p3pp3rf1y.sophisticatedstorage.init.ModBlocks;
import net.p3pp3rf1y.sophisticatedstorage.item.ChestBlockItem;
import net.p3pp3rf1y.sophisticatedstorage.item.StackStorageWrapper;
import net.p3pp3rf1y.sophisticatedstorage.item.StorageBlockItem;

import java.util.Optional;

public class DoubleChestTierUpgradeRecipe extends ShapedRecipe implements IWrapperRecipe<ShapedRecipe> {
	private final ShapedRecipe compose;

	public DoubleChestTierUpgradeRecipe(ShapedRecipe compose) {
		super(compose.getGroup(), compose.category(), compose.pattern, compose.result);
		this.compose = compose;
	}

	@Override
	public ShapedRecipe getCompose() {
		return compose;
	}

	@Override
	public boolean matches(CraftingInput input, Level level) {
		return super.matches(input, level) && getDoubleChest(input).filter(storage -> StorageTierUpgradeRecipe.canUpgrade(storage, level)).isPresent();
	}

	@Override
	public ItemStack assemble(CraftingInput input, HolderLookup.Provider registries) {
		if (getDoubleChest(input).filter(StorageTierUpgradeRecipe::isPrimaryOrUnlinked).isEmpty()) {
			return ItemStack.EMPTY;
		}
		ItemStack upgradedStorage = super.assemble(input, registries);
		getDoubleChest(input).ifPresent(originalStorage -> {
			upgradedStorage.applyComponents(originalStorage.getComponents());
		});
		if (upgradedStorage.has(ModCoreDataComponents.STORAGE_UUID)) {
			StackStorageWrapper storageWrapper = StackStorageWrapper.fromStack(registries, upgradedStorage);
			StorageBlockItem.setNumberOfInventorySlots(upgradedStorage, storageWrapper.getDefaultNumberOfInventorySlots() * 2);
			StorageBlockItem.setNumberOfUpgradeSlots(upgradedStorage, storageWrapper.getDefaultNumberOfUpgradeSlots() * 2);
		}
		return upgradedStorage;
	}

	@Override
	public boolean isSpecial() {
		return true;
	}

	private Optional<ItemStack> getDoubleChest(CraftingInput input) {
		for (int slot = 0; slot < input.size(); slot++) {
			ItemStack slotStack = input.getItem(slot);
			if (slotStack.getItem() instanceof ChestBlockItem && ChestBlockItem.isDoubleChest(slotStack)) {
				return Optional.of(slotStack);
			}
		}

		return Optional.empty();
	}

	@Override
	public RecipeSerializer<?> getSerializer() {
		return ModBlocks.DOUBLE_CHEST_TIER_UPGRADE_RECIPE_SERIALIZER.get();
	}

	public static class Serializer extends RecipeWrapperSerializer<ShapedRecipe, DoubleChestTierUpgradeRecipe> {
		public Serializer() {
			super(DoubleChestTierUpgradeRecipe::new, SHAPED_RECIPE);
		}
	}
}

package net.p3pp3rf1y.sophisticatedstorage.crafting;

import net.minecraft.core.HolderLookup;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.CraftingInput;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.ShapelessRecipe;
import net.minecraft.world.level.Level;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.items.IItemHandler;
import net.p3pp3rf1y.sophisticatedcore.crafting.IWrapperRecipe;
import net.p3pp3rf1y.sophisticatedcore.crafting.RecipeWrapperSerializer;
import net.p3pp3rf1y.sophisticatedcore.util.InventoryHelper;
import net.p3pp3rf1y.sophisticatedstorage.init.ModBlocks;
import net.p3pp3rf1y.sophisticatedstorage.item.StackStorageWrapper;
import net.p3pp3rf1y.sophisticatedstorage.item.WoodStorageBlockItem;

import javax.annotation.Nullable;

import java.util.Optional;

public class ShulkerBoxFromVanillaShapelessRecipe extends ShapelessRecipe implements IWrapperRecipe<ShapelessRecipe> {
	private final ShapelessRecipe compose;

	public ShulkerBoxFromVanillaShapelessRecipe(ShapelessRecipe compose) {
		super(compose.getGroup(), compose.category(), compose.result, compose.getIngredients());
		this.compose = compose;
	}

	@Override
	public boolean matches(CraftingInput input, Level level) {
		return super.matches(input, level) && getVanillaShulkerBox(input)
				.map(storage -> !(storage.getItem() instanceof WoodStorageBlockItem) || !WoodStorageBlockItem.isPacked(storage)).orElse(false);
	}

	@Override
	public ShapelessRecipe getCompose() {
		return compose;
	}

	@Override
	public ItemStack assemble(CraftingInput input, HolderLookup.Provider registries) {
		ItemStack upgradedStorage = super.assemble(input, registries);
		getVanillaShulkerBox(input).ifPresent(vanillaShulkerBox -> {
			@Nullable
			IItemHandler itemCap = vanillaShulkerBox.getCapability(Capabilities.ItemHandler.ITEM);
			if (itemCap != null) {
				StackStorageWrapper wrapper = StackStorageWrapper.fromStack(registries, upgradedStorage);
				wrapper.ensureContentsUuid();
				InventoryHelper.iterate(itemCap, (slot, stack) -> {
					if (!stack.isEmpty()) {
						wrapper.getInventoryHandler().insertItem(stack.copy(), false);
					}
				});
			}
		});
		return upgradedStorage;
	}

	@Override
	public boolean isSpecial() {
		return true;
	}

	private Optional<ItemStack> getVanillaShulkerBox(CraftingInput input) {
		for (int slot = 0; slot < input.size(); slot++) {
			ItemStack slotStack = input.getItem(slot);
			if (slotStack.getItem() instanceof BlockItem blockItem && blockItem.getBlock() instanceof net.minecraft.world.level.block.ShulkerBoxBlock) {
				return Optional.of(slotStack);
			}
		}

		return Optional.empty();
	}

	@Override
	public RecipeSerializer<?> getSerializer() {
		return ModBlocks.SHULKER_BOX_FROM_VANILLA_SHAPELESS_RECIPE_SERIALIZER.get();
	}

	public static class Serializer extends RecipeWrapperSerializer<ShapelessRecipe, ShulkerBoxFromVanillaShapelessRecipe> {
		public Serializer() {
			super(ShulkerBoxFromVanillaShapelessRecipe::new, SHAPELESS_RECIPE);
		}
	}
}

package net.p3pp3rf1y.sophisticatedstorage.crafting;

import net.minecraft.core.HolderLookup;
