import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.Mirror;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;
import org.jspecify.annotations.Nullable;

public class FramedOneWayWindowBlock extends FramedBlock {
    public static final BlockCamoContent GLASS_DUMMY_CAMO = new BlockCamoContent(Blocks.TINTED_GLASS.defaultBlockState());
    public static final String LABEL_WINDOW_FACE = Utils.translationKey("label", "state_cycling.property.one_way_window.window_face");

    public FramedOneWayWindowBlock(Properties props) {
        super(BlockType.FRAMED_ONE_WAY_WINDOW, props);
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        super.createBlockStateDefinition(builder);
        builder.add(PropertyHolder.NULLABLE_FACE);
    }

    @Override
    public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
        super.setPlacedBy(level, pos, state, placer, stack);
        if (placer instanceof Player player && level.getBlockEntity(pos) instanceof FramedOwnableBlockEntity be) {
            be.setOwner(player.getUUID(), true);
        }
    }

    @Override
    public boolean handleBlockLeftClick(BlockState state, Level level, BlockPos pos, Player player) {
        if (player.getMainHandItem().is(FBContent.ITEM_FRAMED_WRENCH.value()) && isOwnedBy(level, pos, player)) {
            if (!level.isClientSide()) {
                if (player.isShiftKeyDown()) {
                    level.setBlockAndUpdate(pos, state.setValue(PropertyHolder.NULLABLE_FACE, NullableDirection.NONE));
                } else {
                    HitResult hit = player.pick(10D, 0, false);
                    if (!(hit instanceof BlockHitResult blockHit)) {
                        return false;
                    }

                    NullableDirection face =  NullableDirection.fromDirection(blockHit.getDirection());
                    level.setBlockAndUpdate(pos, state.setValue(PropertyHolder.NULLABLE_FACE, face));
                }
            }
            return true;
        }
        return false;
    }

    @Override
    protected VoxelShape getOcclusionShape(BlockState state) {
        if (state.getValue(PropertyHolder.NULLABLE_FACE) != NullableDirection.NONE) {
            return Shapes.empty();
        }
        return super.getOcclusionShape(state);
    }

    @Override
    public boolean canOccludeNeighbor(BlockGetter level, BlockPos pos, BlockState state, BlockPos adjPos, BlockState adjState) {
        if (adjState.getBlock() != FBContent.BLOCK_FRAMED_ONE_WAY_WINDOW.value()) {
            return false;
        }
        return state.getValue(PropertyHolder.NULLABLE_FACE) == adjState.getValue(PropertyHolder.NULLABLE_FACE);
    }

    @Override
    public boolean addRunningEffects(BlockState state, Level level, BlockPos pos, Entity entity) {
        if (state.getValue(PropertyHolder.NULLABLE_FACE) == NullableDirection.UP) {
            ParticleHelper.spawnRunningParticles(GLASS_DUMMY_CAMO, level, pos, entity);
            return true;
        }
        return super.addRunningEffects(state, level, pos, entity);
    }

    @Override
    public boolean addLandingEffects(BlockState state, ServerLevel level, BlockPos pos, BlockState sameState, LivingEntity entity, int count) {
        if (state.getValue(PropertyHolder.NULLABLE_FACE) == NullableDirection.UP) {
            ParticleHelper.spawnLandingParticles(GLASS_DUMMY_CAMO, level, pos, entity, count);
            return true;
        }
        return super.addLandingEffects(state, level, pos, sameState, entity, count);
    }

    @Override
    protected BlockState rotate(BlockState state, Rotation rotation) {
        NullableDirection face = state.getValue(PropertyHolder.NULLABLE_FACE);
        return state.setValue(PropertyHolder.NULLABLE_FACE, face.rotate(rotation));
    }

    @Override
    protected BlockState mirror(BlockState state, Mirror mirror) {
        NullableDirection face = state.getValue(PropertyHolder.NULLABLE_FACE);
        return state.setValue(PropertyHolder.NULLABLE_FACE, face.mirror(mirror));
    }

    @Override
    public TriState shouldNotifyBlockEntityOfWrenchRotation(WrenchRotationMode mode, BlockState oldState, BlockState newState) {
        return TriState.DEFAULT;
    }

    @Override
    public BlockState getAppearance(BlockState state, BlockAndLightGetter level, BlockPos pos, Direction side, @Nullable BlockState queryState, @Nullable BlockPos queryPos) {
        Direction dir = state.getValue(PropertyHolder.NULLABLE_FACE).toNullableDirection();
        if (dir == side && queryPos != null) {
            if (DirUtils.dirByNormal(pos, queryPos) == dir) {
                return Blocks.TINTED_GLASS.defaultBlockState();
            }
            if (queryState == null) {
                queryState = level.getBlockState(queryPos);
            }
            if (queryState.is(this) && queryState.getValue(PropertyHolder.NULLABLE_FACE).toNullableDirection() == dir) {
                return Blocks.TINTED_GLASS.defaultBlockState();
            }
            return Blocks.AIR.defaultBlockState();
        }
        return super.getAppearance(state, level, pos, side, queryState, queryPos);
    }

    @Override
    public FramedBlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new FramedOwnableBlockEntity(pos, state);
    }

    @Override
    public BlockState getItemModelSource() {
        return defaultBlockState();
    }

    @Override
    public StateCycleSpec createStateCycleSpec() {
        return StateCycleSpec.builder(this)
                .property(PropertyHolder.NULLABLE_FACE, builder -> builder
                        .values(NullableDirection.CYCLE_ORDER)
                        .printer(LABEL_WINDOW_FACE)
                )
                .build();
    }

    @Override
    public BlockState getJadeRenderState(BlockState state) {
        return state.setValue(PropertyHolder.NULLABLE_FACE, NullableDirection.EAST);
    }

    public static boolean isOwnedBy(BlockGetter level, BlockPos pos, Player player) {
        if (!ServerConfig.VIEW.isOneWayWindowOwnable()) {
            return true;
        }
        if (level.getBlockEntity(pos) instanceof FramedOwnableBlockEntity be) {
            return player.getUUID().equals(be.getOwner());
        }
        return false;
    }
}

package io.github.xfacthd.framedblocks.common.blockentity.special;

import io.github.xfacthd.framedblocks.api.block.blockentity.FramedBlockEntity;
import io.github.xfacthd.framedblocks.api.block.blockentity.NetworkValueInput;
import io.github.xfacthd.framedblocks.api.block.blockentity.RotationSource;
import io.github.xfacthd.framedblocks.api.blueprint.BlueprintData;
import io.github.xfacthd.framedblocks.api.util.DirUtils;
import io.github.xfacthd.framedblocks.api.util.MathUtils;
import io.github.xfacthd.framedblocks.common.FBContent;
import io.github.xfacthd.framedblocks.common.blockentity.PackedCollapsibleBlockOffsets;
import io.github.xfacthd.framedblocks.common.data.PropertyHolder;
import io.github.xfacthd.framedblocks.common.data.collapsible.HammerTarget;
import io.github.xfacthd.framedblocks.common.data.collapsible.NeighborVertex;
import io.github.xfacthd.framedblocks.common.data.collapsible.TargetCalculator;
import io.github.xfacthd.framedblocks.common.data.collapsible.VertexMappings;
import io.github.xfacthd.framedblocks.common.data.component.CollapsibleBlockData;
import io.github.xfacthd.framedblocks.common.data.property.NullableDirection;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.component.DataComponentGetter;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.component.TypedDataComponent;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.component.BlockItemStateProperties;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Mirror;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.model.data.ModelData;
import org.jspecify.annotations.Nullable;

import java.util.Arrays;

public class FramedCollapsibleBlockEntity extends FramedBlockEntity implements CollapsibleBlockEntity {
    public static final int DIRECTIONS = Direction.values().length;
    private static final Direction[] HORIZONTAL_DIRECTIONS = Direction.Plane.HORIZONTAL.stream().toArray(Direction[]::new);
    public static final int VERTEX_COUNT = 4;
    private static final int BIT_PER_VERTEX = 5;
    private static final int VERTEX_MASK = ~(-1 << BIT_PER_VERTEX);

    private int packedOffsets = 0;

    public FramedCollapsibleBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_COLLAPSIBLE_BLOCK.value(), pos, state);
    }

    public void handleDeform(Player player) {
        HitResult hit = player.pick(10D, 1F, false);
        if (!(hit instanceof BlockHitResult blockHit)) {
            return;
        }

        HammerTarget target = TargetCalculator.computeTarget(this, player, blockHit, true, 1F);
        if (target == null) {
            return;
        }

        int vert = vertexFromHit(target.face(), target.pos());
        if (vert == 4) {
            for (int i = 0; i < 4; i++) {
                handleDeformOfVertex(player, target, i);
            }
        } else {
            handleDeformOfVertex(player, target, vert);
        }
    }

    private void handleDeformOfVertex(Player player, HammerTarget target, int vert) {
        Direction oldFace = target.oldFace();
        Direction faceHit = target.face();
        int offset = getVertexOffset(vert);
        if (player.isShiftKeyDown() && oldFace != null && offset > 0) {
            int newOffset = offset - 1;

            applyDeformation(vert, newOffset, faceHit, oldFace);
            deformNeighbors(faceHit, vert, newOffset);
        } else if (!player.isShiftKeyDown() && offset < 16) {
            int newOffset = offset + 1;

            applyDeformation(vert, newOffset, faceHit, oldFace);
            deformNeighbors(faceHit, vert, newOffset);
        }
    }

    private void applyDeformation(int vertex, int offset, Direction faceHit, @Nullable Direction oldFace) {
        offset = Mth.clamp(offset, 0, 16);

        if (offset == getVertexOffset(vertex)) {
            return;
        }

        setVertexOffset(vertex, offset);

        if (offset == 0) {
            boolean noOffsets = true;
            for (int i = 0; i < 4; i++) {
                if (getVertexOffset(i) > 0) {
                    noOffsets = false;
                    break;
                }
            }

            updateStateAndSync(oldFace, noOffsets ? null : oldFace);
        } else {
            updateStateAndSync(oldFace, faceHit);
        }

        setChangedWithoutSignalUpdate();
    }

    private void updateStateAndSync(@Nullable Direction oldFace, @Nullable Direction newFace) {
        if (oldFace != newFace) {
            NullableDirection face = NullableDirection.fromDirection(newFace);
            BlockState newState = getBlockState().setValue(PropertyHolder.NULLABLE_FACE, face);
            level().setBlock(worldPosition, newState, Block.UPDATE_ALL);
        } else {
            level().sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
        }
    }

    private void deformNeighbors(Direction faceHit, int srcVert, int offset) {
        NeighborVertex[] verts = VertexMappings.getNeighbors(faceHit, srcVert);
        for (int i = 0; i < 3; i++) {
            NeighborVertex vert = verts[i];
            BlockPos pos = worldPosition.offset(vert.offset());
            if (level().getBlockEntity(pos) instanceof FramedCollapsibleBlockEntity be) {
                Direction oldFace = be.getCollapsedFace();
                if (oldFace == null || oldFace == faceHit) {
                    be.applyDeformation(vert.targetVert(), offset, faceHit, oldFace);
                }
            }
        }
    }

    private void setVertexOffset(int vertex, int offset) {
        int idx = vertex * BIT_PER_VERTEX;
        int mask = VERTEX_MASK << idx;
        packedOffsets = (packedOffsets & ~mask) | (offset << idx);
    }

    public static int vertexFromHit(Direction faceHit, Vec3 loc) {
        if (DirUtils.isY(faceHit)) {
            double ax = Math.abs((loc.x - .5) * 4D);
            double az = Math.abs((loc.z - .5) * 4D);
            if (ax >= 0D && ax <= 1D && az >= 0D && az <= 1D && az <= (1D - ax)) {
                return 4;
            }

            if ((loc.z < .5F) == (faceHit == Direction.UP)) {
                return loc.x < .5F ? 0 : 3;
            } else {
                return loc.x < .5F ? 1 : 2;
            }
        } else {
            double xz = DirUtils.isX(faceHit) ? loc.z : loc.x;
            double axz = Math.abs((xz - .5) * 4D);
            double ay = Math.abs((loc.y - .5D) * 4D);
            if (axz >= 0D && axz <= 1D && ay >= 0D && ay <= 1D && ay <= (1D - axz)) {
                return 4;
            }

            boolean positive = faceHit == Direction.SOUTH || faceHit == Direction.WEST;
            if (loc.y < .5F) {
                return (xz < .5F) == positive ? 1 : 2;
            } else {
                return (xz < .5F) == positive ? 0 : 3;
            }
        }
    }

    public static int vertexFromCorner(Direction faceHit, Direction dirOne, Direction dirTwo) {
        if (DirUtils.isY(faceHit)) {
            Direction dirX = select(Direction.Axis.X, dirOne, dirTwo);
            Direction dirZ = select(Direction.Axis.Z, dirOne, dirTwo);
            if ((dirZ == Direction.NORTH) == (faceHit == Direction.UP)) {
                return dirX == Direction.WEST ? 0 : 3;
            } else {
                return dirX == Direction.WEST ? 1 : 2;
            }
        } else {
            Direction dirY = select(Direction.Axis.Y, dirOne, dirTwo);
            Direction dirXZ = select(DirUtils.isX(faceHit) ? Direction.Axis.Z : Direction.Axis.X, dirOne, dirTwo);
            boolean positive = faceHit == Direction.SOUTH || faceHit == Direction.WEST;
            if (dirY == Direction.DOWN) {
                return DirUtils.isPositive(dirXZ) != positive ? 1 : 2;
            } else {
                return DirUtils.isPositive(dirXZ) != positive ? 0 : 3;
            }
        }
    }

    private static Direction select(Direction.Axis axis, Direction dirOne, Direction dirTwo) {
        if (dirOne.getAxis() == axis) {
            return dirOne;
        } else if (dirTwo.getAxis() == axis) {
            return dirTwo;
        } else {
            throw new IllegalArgumentException("Neither %s nor %s fit axis %s".formatted(dirOne, dirTwo, axis));
        }
    }

    public @Nullable Direction getCollapsedFace() {
        return getBlockState().getValue(PropertyHolder.NULLABLE_FACE).toNullableDirection();
    }

    public int getVertexOffset(int vertex) {
        return packedOffsets >> (vertex * 5) & 0x1F;
    }

    @Override
    public int getVertexOffset(BlockState state, int vertex) {
        return getVertexOffset(vertex);
    }

    @Override
    public int getPackedOffsets(BlockState state) {
        return packedOffsets;
    }

    @Override
    protected boolean applyExternalRotation(Mirror mirror, Rotation rotation, RotationSource source) {
        int prevOffsets = packedOffsets;
        NullableDirection nullableDir = getBlockState().getValue(PropertyHolder.NULLABLE_FACE);
        if (nullableDir != NullableDirection.NONE && (mirror != Mirror.NONE || rotation != Rotation.NONE)) {
            Direction dir = nullableDir.toDirection();
            int[] offsets = new int[4];
            for (int i = 0; i < 4; i++) {
                offsets[i] = getVertexOffset(i);
            }

            if (mirror != Mirror.NONE) {
                Direction face;
                Direction.Axis mirrorAxis;
                Direction.Axis perpAxis;
                if (DirUtils.isY(dir)) {
                    face = dir;
                    mirrorAxis = DirUtils.getMirrorAxis(mirror);
                    perpAxis = DirUtils.getPerpendicularAxis(mirrorAxis, Direction.Axis.Y);
                } else {
                    NullableDirection unmirrored = nullableDir.rotate(DirUtils.getOppositeRotation(rotation)).mirror(mirror);
                    face = unmirrored.toDirection();
                    mirrorAxis = face.getClockWise().getAxis();
                    perpAxis = Direction.Axis.Y;
                }

                Direction mirrorNeg = mirrorAxis.getNegative();
                Direction mirrorPos = mirrorAxis.getPositive();
                Direction perpNeg = perpAxis.getNegative();
                Direction perpPos = perpAxis.getPositive();
                MathUtils.swap(offsets, vertexFromCorner(face, mirrorNeg, perpNeg), vertexFromCorner(face, mirrorPos, perpNeg));
                MathUtils.swap(offsets, vertexFromCorner(face, mirrorNeg, perpPos), vertexFromCorner(face, mirrorPos, perpPos));
            }

            if (DirUtils.isY(dir) && rotation != Rotation.NONE) {
                if (dir == Direction.UP) {
                    rotation = DirUtils.getOppositeRotation(rotation);
                }
                int[] offsetsCopy = Arrays.copyOf(offsets, offsets.length);
                for (Direction horDir : HORIZONTAL_DIRECTIONS) {
                    Direction outDir = rotation.rotate(horDir);
                    offsets[outDir.get2DDataValue()] = offsetsCopy[horDir.get2DDataValue()];
                }
            }

            for (int i = 0; i < 4; i++) {
                setVertexOffset(i, offsets[i]);
            }
        }
        boolean offsetsChanged = packedOffsets != prevOffsets;
        if (source == RotationSource.STRUCTURE || offsetsChanged) {
            boolean camoChanged = super.applyExternalRotation(mirror, rotation, source);
            return offsetsChanged || camoChanged;
        }
        return false;
    }

    @Override
    protected void attachAdditionalModelData(ModelData.Builder builder) {
        builder.with(PackedCollapsibleBlockOffsets.PROPERTY, new PackedCollapsibleBlockOffsets.Single(packedOffsets));
    }

    @Override
    protected void writeToDataPacket(ValueOutput valueOutput) {
        super.writeToDataPacket(valueOutput);
        valueOutput.putInt("offsets", packedOffsets);
    }

    @Override
    protected void readFromDataPacket(NetworkValueInput input) {
        super.readFromDataPacket(input);

        int packed = input.getIntOr("offsets", 0);
        if (packed != packedOffsets) {
            packedOffsets = packed;

            input.requestRenderUpdate();
            input.requestCullingUpdate();
        }
    }

    @Override
    protected BlueprintData appendCustomBlueprintData(BlueprintData blueprintData) {
        return blueprintData.withCustomData(FBContent.DC_TYPE_COLLAPSIBLE_BLOCK_DATA, new CollapsibleBlockData(packedOffsets));
    }

    @Override
    protected void applyCustomDataFromBlueprint(TypedDataComponent<?> auxData) {
        if (auxData.value() instanceof CollapsibleBlockData(int offsets)) {
            packedOffsets = offsets;
        }
    }

    @Override
    public void removeComponentsFromTag(ValueOutput valueOutput) {
        super.removeComponentsFromTag(valueOutput);
        valueOutput.discard("offsets");
        valueOutput.discard("face");
    }

    @Override
    protected void collectMiscComponents(DataComponentMap.Builder builder) {
        builder.set(FBContent.DC_TYPE_COLLAPSIBLE_BLOCK_DATA, new CollapsibleBlockData(packedOffsets));

        BlockState state = getBlockState();
        BlockItemStateProperties stateProperties = BlockItemStateProperties.EMPTY
                .with(PropertyHolder.NULLABLE_FACE, state)
                .with(PropertyHolder.ROTATE_SPLIT_LINE, state);
        builder.set(DataComponents.BLOCK_STATE, stateProperties);
    }

    @Override
    protected void applyMiscComponents(DataComponentGetter input) {
        CollapsibleBlockData blockData = input.get(FBContent.DC_TYPE_COLLAPSIBLE_BLOCK_DATA);
        if (blockData != null) {
            packedOffsets = blockData.offsets();
        }
    }

    @Override
    public void saveAdditional(ValueOutput valueOutput) {
        super.saveAdditional(valueOutput);
        valueOutput.putInt("offsets", packedOffsets);
    }

    @Override
    public void loadAdditional(ValueInput valueInput) {
        super.loadAdditional(valueInput);
        packedOffsets = valueInput.getIntOr("offsets", 0);
    }

    public static byte[] unpackOffsets(int packed) {
        byte[] offsets = new byte[4];
        for (int i = 0; i < 4; i++) {
            offsets[i] = (byte) (packed >> (i * 5) & 0x1F);
        }
        return offsets;
    }
}

package io.github.xfacthd.framedblocks.common.blockentity.special;

import io.github.xfacthd.framedblocks.api.block.blockentity.FramedBlockEntity;
import io.github.xfacthd.framedblocks.api.block.blockentity.NetworkValueInput;
import io.github.xfacthd.framedblocks.api.blueprint.BlueprintData;
import io.github.xfacthd.framedblocks.common.FBContent;
import io.github.xfacthd.framedblocks.common.data.component.PottedFlower;
import net.minecraft.core.BlockPos;
import net.minecraft.core.component.DataComponentGetter;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.core.component.TypedDataComponent;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.model.data.ModelData;
import net.neoforged.neoforge.model.data.ModelProperty;

import java.util.function.Consumer;

public class FramedFlowerPotBlockEntity extends FramedBlockEntity {
    public static final ModelProperty<Block> FLOWER_BLOCK = new ModelProperty<>();

    private Block flowerBlock = Blocks.AIR;

    public FramedFlowerPotBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_FLOWER_POT.value(), pos, state);
    }

    public void setFlowerBlock(Block flowerBlock) {
        if (flowerBlock != this.flowerBlock) {
            this.flowerBlock = flowerBlock;

            setChangedWithoutSignalUpdate();
            level().sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
        }
    }

    public boolean hasFlowerBlock() {
        return flowerBlock != Blocks.AIR;
    }

    public Block getFlowerBlock() {
        return flowerBlock;
    }

    @Override
    public void addAdditionalDrops(Consumer<ItemStack> drops, boolean dropCamo) {
        super.addAdditionalDrops(drops, dropCamo);
        if (flowerBlock != Blocks.AIR) {
            drops.accept(new ItemStack(flowerBlock));
        }
    }

    @Override
    protected void attachAdditionalModelData(ModelData.Builder builder) {
        builder.with(FLOWER_BLOCK, flowerBlock);
    }

    @Override
    protected void writeToDataPacket(ValueOutput valueOutput) {
        super.writeToDataPacket(valueOutput);
        valueOutput.putString("flower", BuiltInRegistries.BLOCK.getKey(flowerBlock).toString());
    }

    @Override
    protected void readFromDataPacket(NetworkValueInput input) {
        super.readFromDataPacket(input);

        Block flower = BuiltInRegistries.BLOCK.getValue(Identifier.parse(input.getStringOr("flower", "")));
        if (flower != flowerBlock) {
            flowerBlock = flower;
            input.requestRenderUpdate();
        }
    }

    @Override
    protected BlueprintData appendCustomBlueprintData(BlueprintData blueprintData) {
        return blueprintData.withCustomData(FBContent.DC_TYPE_POTTED_FLOWER, new PottedFlower(flowerBlock));
    }

    @Override
    protected void applyCustomDataFromBlueprint(TypedDataComponent<?> auxData) {
        if (auxData.value() instanceof PottedFlower flower && !flower.isEmpty()) {
            flowerBlock = flower.flower();
        }
    }

    @Override
    public void removeComponentsFromTag(ValueOutput valueOutput) {
        super.removeComponentsFromTag(valueOutput);
        valueOutput.discard("flower");
    }

    @Override
    protected void collectMiscComponents(DataComponentMap.Builder builder) {
        if (hasFlowerBlock()) {
            builder.set(FBContent.DC_TYPE_POTTED_FLOWER, new PottedFlower(flowerBlock));
        }
    }

    @Override
    protected void applyMiscComponents(DataComponentGetter input) {
        PottedFlower flower = input.getOrDefault(FBContent.DC_TYPE_POTTED_FLOWER, PottedFlower.EMPTY);
        if (!flower.isEmpty()) {
            flowerBlock = flower.flower();
        }
    }

    @Override
    public void saveAdditional(ValueOutput valueOutput) {
        valueOutput.putString("flower", BuiltInRegistries.BLOCK.getKey(flowerBlock).toString());
        super.saveAdditional(valueOutput);
    }

    @Override
    public void loadAdditional(ValueInput valueInput) {
        super.loadAdditional(valueInput);
        flowerBlock = BuiltInRegistries.BLOCK.getValue(Identifier.tryParse(valueInput.getStringOr("flower", "")));
    }
}

package io.github.xfacthd.framedblocks.common.blockentity.special;

import io.github.xfacthd.framedblocks.api.block.blockentity.FramedBlockEntity;
import io.github.xfacthd.framedblocks.api.block.blockentity.NetworkValueInput;
import io.github.xfacthd.framedblocks.api.util.Utils;
import io.github.xfacthd.framedblocks.common.FBContent;
import io.github.xfacthd.framedblocks.common.data.BlockType;
import io.github.xfacthd.framedblocks.common.data.PropertyHolder;
import io.github.xfacthd.framedblocks.common.data.component.FramedMap;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.protocol.Packet;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.ItemOwner;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.MapItem;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.saveddata.maps.MapId;
import net.minecraft.world.level.saveddata.maps.MapItemSavedData;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.Vec3;

import java.util.Objects;
import java.util.function.Consumer;

public class FramedItemFrameBlockEntity extends FramedBlockEntity implements ItemOwner {
    public static final int ROTATION_STEPS = 8;
    private static final int MAP_UPDATE_INTERVAL = 10;
    public static final String ITEM_NBT_KEY = "item";

    private final boolean glowing;
    private ItemStack heldItem = ItemStack.EMPTY;
    private int rotation = 0;
    private int mapTickOffset = 0;
    private long mapTickCount = 0;

    public FramedItemFrameBlockEntity(BlockPos pos, BlockState state) {
        super(FBContent.BE_TYPE_FRAMED_ITEM_FRAME.value(), pos, state);
        this.glowing = getBlockType() == BlockType.FRAMED_GLOWING_ITEM_FRAME;
    }

    public void tickWithMap() {
        if (mapTickCount % MAP_UPDATE_INTERVAL == 0) {
            if (mapTickCount == 0) {
                // Only start ticking with offset after first tick. Ensures the client will receive the map data ASAP
                mapTickCount = mapTickOffset;
            }

            MapItemSavedData mapData = MapItem.getSavedData(heldItem, level());
            if (mapData != null) {
                MapId mapId = Objects.requireNonNull(heldItem.get(DataComponents.MAP_ID));
                for (Player player : level().players()) {
                    mapData.tickCarriedBy(player, heldItem, null);
                    Packet<?> packet = mapData.getUpdatePacket(mapId, player);
                    if (packet != null) {
                        ((ServerPlayer) player).connection.send(packet);
                    }
                }
            }
        }
        mapTickCount++;
    }

    public InteractionResult handleFrameInteraction(Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (hasItem()) {
            if (!level().isClientSide()) {
                rotation = (rotation + 1) % ROTATION_STEPS;

                playSound(glowing ? SoundEvents.GLOW_ITEM_FRAME_ROTATE_ITEM : SoundEvents.ITEM_FRAME_ROTATE_ITEM);

                setChangedWithoutSignalUpdate();
                level().sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
            }
            return InteractionResult.SUCCESS;
        } else if (!stack.isEmpty() && !hasItem()) {
            if (!level().isClientSide()) {
                setItem(stack);
                if (!player.isCreative()) {
                    stack.shrink(1);
                }
                player.getInventory().setChanged();

                playSound(glowing ? SoundEvents.GLOW_ITEM_FRAME_ADD_ITEM : SoundEvents.ITEM_FRAME_ADD_ITEM);
            }
            return InteractionResult.SUCCESS;
        }
        return InteractionResult.TRY_WITH_EMPTY_HAND;
    }

    public void removeItem(Player player) {
        if (heldItem.getItem() instanceof MapItem) {
            FramedMap map = heldItem.remove(FBContent.DC_TYPE_FRAMED_MAP);
            if (map != null) {
                MapItemSavedData mapData = MapItem.getSavedData(heldItem, level());
                if (mapData instanceof FramedMap.MarkerRemover remover) {
                    remover.framedblocks$removeMapMarker(worldPosition);
                }
            }
        }

        Utils.giveToPlayer(player, heldItem);

        // Don't clear rotation
        setItem(ItemStack.EMPTY);

        playSound(glowing ? SoundEvents.GLOW_ITEM_FRAME_REMOVE_ITEM : SoundEvents.ITEM_FRAME_REMOVE_ITEM);
    }

    private void setItem(ItemStack item) {
        if (item.isEmpty()) {
            heldItem = ItemStack.EMPTY;
        } else {
            heldItem = item.copy();
            heldItem.setCount(1);

            if (heldItem.getItem() instanceof MapItem) {
                Direction dir = getBlockState().getValue(BlockStateProperties.FACING).getOpposite();
                heldItem.set(FBContent.DC_TYPE_FRAMED_MAP, new FramedMap(worldPosition, dir));
            }
        }

        setChangedWithoutSignalUpdate();
        if (!changeMapStateIfNeeded()) {
            level().sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), Block.UPDATE_ALL);
        }
    }

    public boolean hasItem() {
        return !heldItem.isEmpty();
    }

    public ItemStack getItem() {
        return heldItem;
    }

    public ItemStack getCloneItem() {
        ItemStack stack = heldItem.copy();
        stack.remove(FBContent.DC_TYPE_FRAMED_MAP);
        return stack;
    }

    public int getRotation() {
        return rotation;
    }

    public boolean isGlowingFrame() {
        return glowing;
    }

    private boolean changeMapStateIfNeeded() {
        boolean mapItem = !heldItem.isEmpty() && heldItem.getItem() instanceof MapItem;
        boolean mapState = getBlockState().getValue(PropertyHolder.MAP_FRAME);

        if (mapItem != mapState) {
            level().setBlockAndUpdate(worldPosition, getBlockState().setValue(PropertyHolder.MAP_FRAME, mapItem));
            mapTickCount = mapTickOffset = mapItem ? level().getRandom().nextInt(MAP_UPDATE_INTERVAL) : 0;
            return true;
        }
        return false;
    }

    private void playSound(SoundEvent sound) {
        level().playSound(null, worldPosition.getX(), worldPosition.getY(), worldPosition.getZ(), sound, SoundSource.BLOCKS, 1F, 1F);
    }

    @Override
    public void addAdditionalDrops(Consumer<ItemStack> drops, boolean dropCamo) {
        super.addAdditionalDrops(drops, dropCamo);
        if (!heldItem.isEmpty()) {
            drops.accept(getCloneItem());
        }
    }

    @Override
    public Vec3 position() {
        return new Vec3(worldPosition);
    }

    @Override
    public float getVisualRotationYInDegrees() {
        Direction facing = getBlockState().getValue(BlockStateProperties.FACING).getOpposite();
        int yRot = facing.getAxis().isVertical() ? 90 * facing.getAxisDirection().getStep() : 0;
        return Mth.wrapDegrees(180 + facing.get2DDataValue() * 90 + getRotation() * 45 + yRot);
    }

    // Network

    @Override
    protected void readFromDataPacket(NetworkValueInput input) {
        super.readFromDataPacket(input);

        heldItem = input.read(ITEM_NBT_KEY, ItemStack.OPTIONAL_CODEC).orElse(ItemStack.EMPTY);
        rotation = input.getByteOr("rotation", (byte) 0);
    }

    @Override
    protected void writeToDataPacket(ValueOutput valueOutput) {
        super.writeToDataPacket(valueOutput);
        valueOutput.store(ITEM_NBT_KEY, ItemStack.OPTIONAL_CODEC, heldItem);
        valueOutput.putByte("rotation", (byte) rotation);
    }

    // NBT

    @Override
    public void loadAdditional(ValueInput valueInput) {
        super.loadAdditional(valueInput);

        heldItem = valueInput.read(ITEM_NBT_KEY, ItemStack.OPTIONAL_CODEC).orElse(ItemStack.EMPTY);
        rotation = valueInput.getByteOr("rotation", (byte) 0);
        mapTickOffset = valueInput.getIntOr("map_tick_offset", 0);
    }

    @Override
    public void saveAdditional(ValueOutput valueInput) {
        super.saveAdditional(valueInput);

        valueInput.store(ITEM_NBT_KEY, ItemStack.OPTIONAL_CODEC, heldItem);
        valueInput.putByte("rotation", (byte) rotation);
        valueInput.putInt("map_tick_offset", mapTickOffset);
    }
}

